{"function":"() => {
// Tab-order approximation: list focusable elements in DOM order incl. shadow
const res = [];
const walk = (root) => {
  for (const el of root.querySelectorAll('*')) {
    if (el.shadowRoot) walk(el.shadowRoot);
    if (el.tabIndex >= 0 && !el.disabled && (el.matches('a[href],button,input,select,textarea,[tabindex]'))) {
      const r = el.getBoundingClientRect();
      if (r.width>0) res.push(el.tagName + (el.id?'#'+el.id:'') + ' ' + (el.getAttribute('aria-label')||el.textContent.trim().slice(0,25)) + ` [${Math.round(r.width)}x${Math.round(r.height)}]`);
    }
  }
};
walk(document);
return res.slice(0,40);
}"}

